package dev.kuan.kuanperion.automation.pets;
import dev.kuan.kuanperion.automation.*;import java.util.*;import java.math.BigDecimal;
/** Synthetic identities only. Official public schema observation is not a live George menu/price test. */
public final class PetSalePreflightTest {
 static void check(boolean b,String m){if(!b)throw new AssertionError(m);}static final String A="11111111111111111111111111111111",B="22222222222222222222222222222222";
 public static String plain(){return "{\"type\":\"SLUG\",\"tier\":\"EPIC\",\"exp\":0.0,\"active\":false,\"candyUsed\":0,\"petSoulbound\":false,\"noMove\":false,\"hideInfo\":false,\"hideRightClick\":false}";}
 static ItemSnapshot item(String uuid,boolean protect){return new ItemSnapshot("PET","minecraft:player_head",uuid,"[Lvl 1] Slug","pet-"+uuid,1,List.of(),protect);}
 static PetSalePreflight.Pet pet(int slot,String uuid,String json,boolean protect){return new PetSalePreflight.Pet(slot,item(uuid,protect),PetSalePreflight.metadata(json,uuid).orElseThrow());}
 static final ItemSnapshot AIR=new ItemSnapshot("","minecraft:air","","","",0,List.of(),true);
 static Map<Integer,ItemSnapshot> inventory(List<PetSalePreflight.Pet> pets){var inv=new HashMap<Integer,ItemSnapshot>();for(int i=0;i<43;i++)inv.put(i,AIR);pets.forEach(p->inv.put(p.slot(),p.item()));return inv;}
 static PetSalePreflight.Rules rules(){return new PetSalePreflight.Rules(Set.of(new PetSalePreflight.Kind("SLUG","EPIC")),BigDecimal.ZERO,2,Set.of());}
 public static void main(String[]args){
  var a=pet(9,A,plain(),false);var b=pet(10,B,plain(),false);var pets=List.of(b,a);var inv=inventory(pets);check(PetSalePreflight.select(pets,inv,PetSalePreflight.Rules.defaults()).isEmpty(),"defaults grant no pet disposal authority");var p=PetSalePreflight.select(pets,inv,rules()).orElseThrow();check(p.pets().equals(List.of(a,b)),"exact type/rarity and stable main-inventory order, not display-name substring");inv.put(42,item(B,false));check(!PetSalePreflight.stillMatches(p,inv)&&p.baseline().get(42).count()==0,"immutable complete43 baseline includes saddle/body/offhand");
  var protectedRules=new PetSalePreflight.Rules(rules().allowed(),BigDecimal.ZERO,2,Set.of("11111111-1111-1111-1111-111111111111"));check(PetSalePreflight.select(List.of(a),inventory(List.of(a)),protectedRules).isEmpty(),"canonical protected UUID veto");
  for(String json:List.of(plain().replace("\"exp\":0.0","\"exp\":1.0"),plain().replace("\"active\":false","\"active\":true"),plain().replace("\"petSoulbound\":false","\"petSoulbound\":true"),plain().replace("\"noMove\":false","\"noMove\":true"),plain().replace("\"hideInfo\":false","\"hideInfo\":true"),plain().replace("\"hideRightClick\":false","\"hideRightClick\":true"),plain().replace("\"candyUsed\":0","\"candyUsed\":1"),plain().replace("}",",\"heldItem\":\"VALUABLE_ITEM\"}"),plain().replace("}",",\"skin\":\"VALUABLE_SKIN\"}"),plain().replace("}",",\"uniqueId\":\"unreviewed-identity\"}"),plain().replace("}",",\"extraData\":{\"counter\":1}}"))){var blocked=pet(9,A,json,false);check(PetSalePreflight.select(List.of(blocked),inventory(List.of(blocked)),rules()).isEmpty(),"XP, active/soulbound/noMove/candy/attachment/cosmetic/unreviewed extras always prevent this authorized fresh sale");}
  var favorite=pet(9,A,plain(),true);check(PetSalePreflight.select(List.of(favorite),inventory(List.of(favorite)),rules()).isEmpty(),"native favorite/lock/equipment protection wins");var hotbar=pet(0,A,plain(),false);check(PetSalePreflight.select(List.of(hotbar),inventory(List.of(hotbar)),rules()).isEmpty(),"no hotbar pet selection");
  var duplicate=pet(10,A,plain(),false);check(PetSalePreflight.select(List.of(a,duplicate),inventory(List.of(a,duplicate)),rules()).isEmpty(),"duplicate pet identity blocks the snapshot, not just a slot");var missing=inventory(List.of(a));missing.remove(42);check(PetSalePreflight.select(List.of(a),missing,rules()).isEmpty(),"partial inventory not authorization");missing=inventory(List.of(a));missing.put(11,item(B,false));check(PetSalePreflight.select(List.of(a),missing,rules()).isEmpty(),"unprojected PET cannot hide duplicate or unreviewed metadata");
  check(PetSalePreflight.metadata(plain().replace("}",",\"uuid\":\"11111111-1111-1111-1111-111111111111\"}"),A).isPresent(),"optional embedded UUID must agree with authoritative item UUID");
  for(String bad:List.of(plain().replace("}",",\"uuid\":\""+B+"\"}"),plain().replace("}",",\"exp\":0}"),plain().replace("\"exp\":0.0","\"exp\":\"0\""),plain().replace("\"exp\":0.0","\"exp\":-1"),plain().replace("\"exp\":0.0","\"exp\":1e1000000"),plain().replace("\"petSoulbound\":false,",""),plain().replace("}",",\"newProtection\":false}"),plain()+"{}",plain().replace("}",",\"extraData\":{\"a\":1,\"a\":2}}"))){check(PetSalePreflight.metadata(bad,A).isEmpty(),"malformed/duplicate/unknown/unbounded metadata never becomes a sellable pet");}
  check(PetSalePreflight.metadata(plain(),"not-a-uuid").isEmpty(),"display name cannot replace missing native identity");
  check(PetSalePreflight.metadata(plain(),"00000000000000000000000000000000").isEmpty(),"nil UUID cannot identify an individually authorized pet");
  System.out.println("PetSalePreflightTest: PASS (strict current-observed metadata/UUID/flags, explicit type+rarity+XP caps, protected complete43 baseline and immutable plan; no menu/price/click authority)");
 }
}
